H=Path(__file__).resolve().parent;O=H/'Ausgabe';read=lambda n:json.loads((O/n).read_text());check=read('Innenverkabelung_Pruefung.json');mass=read('Materialvergleich.json');switch=read('Umschalter_Pruefung.json');sweep=read('Freiraum_Pruefung.json');sha=hashlib.sha256((O/'Quad_HEPS_Innenverkabelung.FCStd').read_bytes()).hexdigest();assert check['native_sha256']==switch['native_sha256']==sweep['native_sha256']==sha
